registerItem({
  id: 312800,
  onEquip(ctx) {
    let $g;
    $g = ctx.getenchantgrade();
    ctx.bonus2("bMagicAddEle", "Ele_Poison", 10);
    ctx.bonus2("bAddEle", "Ele_Poison", 10);
    ctx.bonus2("bMagicAddEle", "Ele_Neutral", 10);
    ctx.bonus2("bAddEle", "Ele_Neutral", 10);
    if ($g >= "ENCHANTGRADE_D") {
      ctx.bonus2("bMagicAddEle", "Ele_Poison", 4);
      ctx.bonus2("bAddEle", "Ele_Poison", 4);
      ctx.bonus2("bMagicAddEle", "Ele_Neutral", 4);
      ctx.bonus2("bAddEle", "Ele_Neutral", 4);
      if ($g >= "ENCHANTGRADE_C") {
        ctx.bonus2("bMagicAddEle", "Ele_Poison", 4);
        ctx.bonus2("bAddEle", "Ele_Poison", 4);
        ctx.bonus2("bMagicAddEle", "Ele_Neutral", 4);
        ctx.bonus2("bAddEle", "Ele_Neutral", 4);
        if ($g >= "ENCHANTGRADE_B") {
          ctx.bonus2("bMagicAddEle", "Ele_Poison", 6);
          ctx.bonus2("bAddEle", "Ele_Poison", 6);
          ctx.bonus2("bMagicAddEle", "Ele_Neutral", 6);
          ctx.bonus2("bAddEle", "Ele_Neutral", 6);
          if ($g >= "ENCHANTGRADE_A") {
            ctx.bonus2("bMagicAddEle", "Ele_Poison", 6);
            ctx.bonus2("bAddEle", "Ele_Poison", 6);
            ctx.bonus2("bMagicAddEle", "Ele_Neutral", 6);
            ctx.bonus2("bAddEle", "Ele_Neutral", 6);
          }
        }
      }
    }

  },
});

